tool_input.command:
"=== 1933 监听 ==="; $c=Get-NetTCPConnection -LocalPort 1933 -State Listen -ErrorAction SilentlyContinue; if($c){ $c | Select-Object -First 1 | ForEach-Object { $p=Get-Process -Id $_.OwningProcess -ErrorAction SilentlyContinue; "LISTENING pid=$($_.OwningProcess) name=$($p.ProcessName) start=$($p.StartTime)" } } else { "无监听 (1933 DOWN)" }
"=== /health ==="; try { $h=Invoke-RestMethod -Uri 'http://127.0.0.1:1933/health' -TimeoutSec 5; ConvertTo-Json $h -Compress } catch { "ERR: $($_.Exception.Message.Split([char]10)[0])" }
"=== openviking-server 进程 ==="; Get-Process -Name openviking-server,python,openviking-server* -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -like '*openviking*' } | ForEach-Object { "pid=$($_.Id) name=$($_.ProcessName) start=$($_.StartTime)" }
